import React from 'react';

export default function StudentDashboard({ userName, userId, handleLogout }) {
  
  return (
    <div style={{ padding: '40px', backgroundColor: '#f8fafc' }}>
      {/* කොහේ හරි තැනක ශිෂ්‍යයාගේ නම පෙන්වන්න ලියලා තියෙන තැනට කෙලින්ම userName දාන්න */}
      <h2>Student Dashboard - {userName}</h2>
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(300px, 1fr))', gap: '20px' }}>
        {myCourses.map((course, index) => (
          <div key={index} style={{ background: '#fff', padding: '25px', borderRadius: '15px', boxShadow: '0 4px 6px rgba(0,0,0,0.05)' }}>
            <h3 style={{ marginBottom: '10px' }}>{course.title}</h3>
            <p style={{ color: '#666' }}>Progress: <strong>{course.progress}</strong></p>
            <div style={{ display: 'flex', gap: '15px', marginTop: '15px' }}>
              <button style={{ padding: '8px 15px', borderRadius: '6px', border: 'none', background: '#e2e8f0', cursor: 'pointer' }}>Videos ({course.videos})</button>
              <button style={{ padding: '8px 15px', borderRadius: '6px', border: 'none', background: '#d8f3dc', cursor: 'pointer' }}>Quizzes ({course.quizzes})</button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}
